1	/* Milestone 1: the complete core red-black tree -- rb_create, rb_insert
2	 * with rotations and CLRS-style insert fixup, rb_find, rb_destroy,
3	 * rb_size, rb_validate, and rb_foreach.
4	 *
5	 * Milestone 2: rb_delete, built on CLRS's transplant + delete-fixup.
6	 *
7	 * Leaf representation: a missing child is NULL, permanently -- there is no
8	 * shared sentinel node. NULL is treated as black for all red-black color
9	 * logic (see color_of()); rotations/fixup/validate all check for NULL
10	 * rather than dereference a sentinel's color field. This is also why
11	 * delete_fixup takes an explicit x_parent argument instead of reading
12	 * x->parent the way CLRS does with its sentinel: x itself may be NULL,
13	 * and NULL has no parent pointer to read.
14	 */
15	#include "rbtree.h"
16	
17	#include <stdlib.h>
18	#include <string.h>
19	
20	enum rb_color { RB_RED, RB_BLACK };
21	
22	struct rb_node {
23	    char           *key;      /* owned copy, NUL-terminated */
24	    void           *value;    /* owned only if t->value_free != NULL */
25	    enum rb_color   color;    /* read by insert_fixup, delete_fixup, and validate */
26	    struct rb_node *left;
27	    struct rb_node *right;
28	    struct rb_node *parent;   /* NULL for root */
29	};
30	
31	struct rbtree {
32	    struct rb_node   *root;       /* NULL when empty */
33	    size_t            size;
34	    rb_value_free_fn  value_free; /* may be NULL */
35	};
36	
37	/* Allocation seam: every malloc/free in this file routes through these so
38	 * a later slice (or a test harness) can hook allocation without touching
39	 * call sites. */
40	static void *rb_malloc(size_t n) { return malloc(n); }
41	static void  rb_free(void *p)    { free(p); }
42	
43	/* NULL counts as a black leaf everywhere in red-black logic, since there
44	 * is no sentinel node to hold a color. */
45	static enum rb_color color_of(const struct rb_node *n) { return n ? n->color : RB_BLACK; }
46	
47	/* Promotes x->right to x's place; x becomes its former right child's left
48	 * child. Order matters: capture the mover (y) first, migrate the orphaned
49	 * middle subtree next (read before overwrite), reparent y into the
50	 * grandparent slot (or root) third, link x under y last. */
51	static void rotate_left(rbtree_t *t, struct rb_node *x) {
52	    struct rb_node *y = x->right;
53	
54	    x->right = y->left;
55	    if (y->left != NULL) {
56	        y->left->parent = x;
57	    }
58	
59	    y->parent = x->parent;
60	    if (x->parent == NULL) {
61	        t->root = y;
62	    } else if (x == x->parent->left) {
63	        x->parent->left = y;
64	    } else {
65	        x->parent->right = y;
66	    }
67	
68	    y->left = x;
69	    x->parent = y;
70	}
71	
72	/* Mirror of rotate_left: promotes x->left to x's place. */
73	static void rotate_right(rbtree_t *t, struct rb_node *x) {
74	    struct rb_node *y = x->left;
75	
76	    x->left = y->right;
77	    if (y->right != NULL) {
78	        y->right->parent = x;
79	    }
80	
81	    y->parent = x->parent;
82	    if (x->parent == NULL) {
83	        t->root = y;
84	    } else if (x == x->parent->right) {
85	        x->parent->right = y;
86	    } else {
87	        x->parent->left = y;
88	    }
89	
90	    y->right = x;
91	    x->parent = y;
92	}
93	
94	/* Restores red-black properties after inserting red node z.
95	 * Loop invariant: z is red, and the only possible violation is a red-red
96	 * edge between z and z->parent -- every other red-black property holds. */
97	static void insert_fixup(rbtree_t *t, struct rb_node *z) {
98	    while (color_of(z->parent) == RB_RED) {
99	        if (z->parent == z->parent->parent->left) {
100	            struct rb_node *uncle = z->parent->parent->right;
101	            if (color_of(uncle) == RB_RED) {
102	                /* Case 1: uncle red -- recolor only, push violation up. */
103	                z->parent->color = RB_BLACK;
104	                uncle->color = RB_BLACK;
105	                z->parent->parent->color = RB_RED;
106	                z = z->parent->parent;
107	            } else {
108	                if (z == z->parent->right) {
109	                    /* Case 2: triangle -- rotate at parent to form a line. */
110	                    z = z->parent;
111	                    rotate_left(t, z);
112	                }
113	                /* Case 3: line -- recolor then rotate at grandparent. */
114	                z->parent->color = RB_BLACK;
115	                z->parent->parent->color = RB_RED;
116	                rotate_right(t, z->parent->parent);
117	            }
118	        } else {
119	            /* Mirror: parent is a right child; uncle is grandparent->left;
120	             * Case 2 uses rotate_right, Case 3 uses rotate_left. */
121	            struct rb_node *uncle = z->parent->parent->left;
122	            if (color_of(uncle) == RB_RED) {
123	                z->parent->color = RB_BLACK;
124	                uncle->color = RB_BLACK;
125	                z->parent->parent->color = RB_RED;
126	                z = z->parent->parent;
127	            } else {
128	                if (z == z->parent->left) {
129	                    z = z->parent;
130	                    rotate_right(t, z);
131	                }
132	                z->parent->color = RB_BLACK;
133	                z->parent->parent->color = RB_RED;
134	                rotate_left(t, z->parent->parent);
135	            }
136	        }
137	    }
138	    t->root->color = RB_BLACK;
139	}
140	
141	rbtree_t *rb_create(rb_value_free_fn value_free) {
142	    struct rbtree *t = rb_malloc(sizeof *t);
143	    if (t == NULL) {
144	        return NULL;
145	    }
146	
147	    t->root = NULL;
148	    t->size = 0;
149	    t->value_free = value_free;
150	    return t;
151	}
152	
153	int rb_insert(rbtree_t *t, const char *key, void *value) {
154	    if (t == NULL || key == NULL) {
155	        return -1;
156	    }
157	
158	    struct rb_node *parent = NULL;
159	    struct rb_node *cur = t->root;
160	    int cmp = 0;
161	
162	    /* cur descends the BST; parent trails one level behind; parent is
163	     * where the new node attaches if cur becomes NULL. */
164	    while (cur != NULL) {
165	        cmp = strcmp(key, cur->key);
166	        if (cmp == 0) {
167	            /* Overwrite path: same key reused verbatim, no allocation
168	             * is possible or needed on this path. */
169	            if (t->value_free != NULL) {
170	                t->value_free(cur->value);
171	            }
172	            cur->value = value;
173	            return 0;
174	        }
175	        parent = cur;
176	        cur = (cmp < 0) ? cur->left : cur->right;
177	    }
178	
179	    size_t keylen = strlen(key);
180	    char *keycopy = NULL;
181	    struct rb_node *node = NULL;
182	
183	    keycopy = rb_malloc(keylen + 1);
184	    if (keycopy == NULL) {
185	        goto fail;
186	    }
187	    memcpy(keycopy, key, keylen + 1);
188	
189	    node = rb_malloc(sizeof *node);
190	    if (node == NULL) {
191	        goto fail;
192	    }
193	
194	    node->key = keycopy;
195	    node->value = value;
196	    node->color = RB_RED;
197	    node->left = NULL;
198	    node->right = NULL;
199	    node->parent = parent;
200	
201	    if (parent == NULL) {
202	        node->color = RB_BLACK; /* redundant-but-harmless: insert_fixup's
203	                                  * tail line also guarantees this on every
204	                                  * call; kept as a self-documenting base
205	                                  * case for the empty-tree fast path. */
206	        t->root = node;
207	    } else if (cmp < 0) {
208	        parent->left = node;
209	    } else {
210	        parent->right = node;
211	    }
212	    insert_fixup(t, node);
213	    t->size++;
214	    return 0;
215	
216	fail:
217	    rb_free(keycopy);
218	    rb_free(node);
219	    return -1;
220	}
221	
222	void *rb_find(const rbtree_t *t, const char *key) {
223	    if (t == NULL || key == NULL) {
224	        return NULL;
225	    }
226	
227	    /* cur is the current candidate subtree root; the loop terminates on
228	     * a match or when a leaf (NULL child) is passed. */
229	    const struct rb_node *cur = t->root;
230	    while (cur != NULL) {
231	        int cmp = strcmp(key, cur->key);
232	        if (cmp == 0) {
233	            return cur->value;
234	        }
235	        cur = (cmp < 0) ? cur->left : cur->right;
236	    }
237	    return NULL;
238	}
239	
240	static void free_subtree(struct rb_node *n, rb_value_free_fn value_free) {
241	    if (n == NULL) {
242	        return;
243	    }
244	    free_subtree(n->left, value_free);
245	    free_subtree(n->right, value_free);
246	    rb_free(n->key);
247	    if (value_free != NULL) {
248	        value_free(n->value);
249	    }
250	    rb_free(n);
251	}
252	
253	void rb_destroy(rbtree_t *t) {
254	    if (t == NULL) {
255	        return;
256	    }
257	    free_subtree(t->root, t->value_free);
258	    rb_free(t);
259	}
260	
261	static struct rb_node *find_node(rbtree_t *t, const char *key) {
262	    struct rb_node *cur = t->root;
263	    while (cur != NULL) {
264	        int cmp = strcmp(key, cur->key);
265	        if (cmp == 0) {
266	            return cur;
267	        }
268	        cur = (cmp < 0) ? cur->left : cur->right;
269	    }
270	    return NULL;
271	}
272	
273	/* Descends left from n; loop invariant: any key smaller than n->key (if
274	 * one exists in this subtree) lies in n->left. */
275	static struct rb_node *tree_minimum(struct rb_node *n) {
276	    while (n->left != NULL) {
277	        n = n->left;
278	    }
279	    return n;
280	}
281	
282	/* Replaces the subtree rooted at u with the subtree rooted at v, relinking
283	 * u's parent (or t->root) to point at v. v may be NULL. */
284	static void rb_transplant(rbtree_t *t, struct rb_node *u, struct rb_node *v) {
285	    if (u->parent == NULL) {
286	        t->root = v;
287	    } else if (u == u->parent->left) {
288	        u->parent->left = v;
289	    } else {
290	        u->parent->right = v;
291	    }
292	    if (v != NULL) {
293	        v->parent = u->parent;
294	    }
295	}
296	
297	/* Restores red-black properties after a black node was spliced out,
298	 * represented by x (possibly NULL) carrying one extra unit of black.
299	 * x_parent is x's parent even when x is NULL, since NULL has no parent
300	 * pointer of its own to read.
301	 * Loop invariant: every red-black property holds except that x's subtree
302	 * is short one black node on every root-to-leaf path through it. */
303	static void delete_fixup(rbtree_t *t, struct rb_node *x, struct rb_node *x_parent) {
304	    while (x != t->root && color_of(x) == RB_BLACK) {
305	        if (x == x_parent->left) {
306	            struct rb_node *w = x_parent->right;
307	            if (color_of(w) == RB_RED) {
308	                /* Case 1: red sibling -- rotate to expose a black sibling. */
309	                w->color = RB_BLACK;
310	                x_parent->color = RB_RED;
311	                rotate_left(t, x_parent);
312	                w = x_parent->right;
313	            }
314	            if (color_of(w->left) == RB_BLACK && color_of(w->right) == RB_BLACK) {
315	                /* Case 2: black sibling, both nephews black -- recolor,
316	                 * push the extra black up to the parent. */
317	                w->color = RB_RED;
318	                x = x_parent;
319	                x_parent = x->parent;
320	            } else {
321	                if (color_of(w->right) == RB_BLACK) {
322	                    /* Case 3: near nephew red, far nephew black -- rotate
323	                     * at w to reshape into Case 4. */
324	                    w->left->color = RB_BLACK;
325	                    w->color = RB_RED;
326	                    rotate_right(t, w);
327	                    w = x_parent->right;
328	                }
329	                /* Case 4: far nephew red -- recolor and rotate; terminal. */
330	                w->color = x_parent->color;
331	                x_parent->color = RB_BLACK;
332	                w->right->color = RB_BLACK;
333	                rotate_left(t, x_parent);
334	                x = t->root;
335	            }
336	        } else {
337	            /* Mirror: x is a right child; sibling w is x_parent->left. */
338	            struct rb_node *w = x_parent->left;
339	            if (color_of(w) == RB_RED) {
340	                w->color = RB_BLACK;
341	                x_parent->color = RB_RED;
342	                rotate_right(t, x_parent);
343	                w = x_parent->left;
344	            }
345	            if (color_of(w->right) == RB_BLACK && color_of(w->left) == RB_BLACK) {
346	                w->color = RB_RED;
347	                x = x_parent;
348	                x_parent = x->parent;
349	            } else {
350	                if (color_of(w->left) == RB_BLACK) {
351	                    w->right->color = RB_BLACK;
352	                    w->color = RB_RED;
353	                    rotate_left(t, w);
354	                    w = x_parent->left;
355	                }
356	                w->color = x_parent->color;
357	                x_parent->color = RB_BLACK;
358	                w->left->color = RB_BLACK;
359	                rotate_right(t, x_parent);
360	                x = t->root;
361	            }
362	        }
363	    }
364	    if (x != NULL) {
365	        x->color = RB_BLACK;
366	    }
367	}
368	
369	int rb_delete(rbtree_t *t, const char *key) {
370	    if (t == NULL || key == NULL) {
371	        return -1;
372	    }
373	
374	    struct rb_node *z = find_node(t, key);
375	    if (z == NULL) {
376	        return -1;
377	    }
378	
379	    struct rb_node *y = z;
380	    enum rb_color y_original_color = y->color;
381	    struct rb_node *x;
382	    struct rb_node *x_parent;
383	
384	    if (z->left == NULL) {
385	        x = z->right;
386	        x_parent = z->parent;
387	        rb_transplant(t, z, z->right);
388	    } else if (z->right == NULL) {
389	        x = z->left;
390	        x_parent = z->parent;
391	        rb_transplant(t, z, z->left);
392	    } else {
393	        y = tree_minimum(z->right);
394	        y_original_color = y->color;
395	        x = y->right;
396	        if (y->parent == z) {
397	            x_parent = y;
398	        } else {
399	            x_parent = y->parent;
400	            rb_transplant(t, y, y->right);
401	            y->right = z->right;
402	            y->right->parent = y;
403	        }
404	        rb_transplant(t, z, y);
405	        y->left = z->left;
406	        y->left->parent = y;
407	        y->color = z->color;
408	    }
409	
410	    rb_free(z->key);
411	    if (t->value_free != NULL) {
412	        t->value_free(z->value);
413	    }
414	    rb_free(z);
415	    t->size--;
416	
417	    if (y_original_color == RB_BLACK) {
418	        delete_fixup(t, x, x_parent);
419	    }
420	    return 0;
421	}
422	
423	size_t rb_size(const rbtree_t *t) {
424	    if (t == NULL) {
425	        return 0;
426	    }
427	    return t->size;
428	}
429	
430	static void foreach_subtree(const struct rb_node *n,
431	                             void (*fn)(const char *key, void *value, void *ctx),
432	                             void *ctx) {
433	    if (n == NULL) {
434	        return;
435	    }
436	    foreach_subtree(n->left, fn, ctx);
437	    fn(n->key, n->value, ctx);
438	    foreach_subtree(n->right, fn, ctx);
439	}
440	
441	void rb_foreach(const rbtree_t *t,
442	                void (*fn)(const char *key, void *value, void *ctx),
443	                void *ctx) {
444	    if (t == NULL || fn == NULL) {
445	        return;
446	    }
447	    foreach_subtree(t->root, fn, ctx);
448	}
449	
450	#define RB_INVALID (-1)
451	
452	/* Returns the subtree's black-height on success, RB_INVALID if any
453	 * red-black invariant, BST-ordering rule, or parent-pointer link is
454	 * violated anywhere in it. lo/hi are exclusive bounds inherited from
455	 * ancestor keys, NULL meaning unbounded. *count is incremented once per
456	 * visited node, so the caller can cross-check it against t->size
457	 * (Invariant 5, Section 9). */
458	static int validate_subtree(const struct rb_node *n, const struct rb_node *parent,
459	                             const char *lo, const char *hi, size_t *count) {
460	    if (n == NULL) {
461	        return 0;
462	    }
463	    (*count)++;
464	    if (n->parent != parent) {
465	        return RB_INVALID;
466	    }
467	    if ((lo != NULL && strcmp(n->key, lo) <= 0) ||
468	        (hi != NULL && strcmp(n->key, hi) >= 0)) {
469	        return RB_INVALID;
470	    }
471	    if (n->color == RB_RED &&
472	        (color_of(n->left) == RB_RED || color_of(n->right) == RB_RED)) {
473	        return RB_INVALID;
474	    }
475	
476	    int lbh = validate_subtree(n->left, n, lo, n->key, count);
477	    if (lbh == RB_INVALID) {
478	        return RB_INVALID;
479	    }
480	    int rbh = validate_subtree(n->right, n, n->key, hi, count);
481	    if (rbh == RB_INVALID || rbh != lbh) {
482	        return RB_INVALID;
483	    }
484	
485	    return lbh + (n->color == RB_BLACK ? 1 : 0);
486	}
487	
488	int rb_validate(const rbtree_t *t) {
489	    if (t == NULL) {
490	        return 0; /* consistent with rb_size/rb_find: NULL means "empty" */
491	    }
492	    if (t->root != NULL && (t->root->parent != NULL || t->root->color != RB_BLACK)) {
493	        return -1;
494	    }
495	    size_t count = 0;
496	    if (validate_subtree(t->root, NULL, NULL, NULL, &count) == RB_INVALID) {
497	        return -1;
498	    }
499	    return count == t->size ? 0 : -1;
500	}
