static void free_subtree(struct rb_node *n, rb_value_free_fn value_free) {
    if (n == NULL) {
        return;
    }
    free_subtree(n->left, value_free);
    free_subtree(n->right, value_free);
    rb_free(n->key);
    if (value_free != NULL) {
        value_free(n->value);
